// Package store implements the models
// interfaces with queries generated by sqlc. The generated code lives in
// package sqlcgen; edit queries.sql and regenerate it instead of editing it.
package store

import (
	"context"
	"fmt"

	"example.com/shop/internal/models"
	"example.com/shop/internal/store/sqlcgen"
)

// itemStore is a models.ItemStore backed by sqlc queries.
type itemStore struct {
	q *sqlcgen.Queries
}

// New returns a models.ItemStore that stores items in db.
func New(db sqlcgen.DBTX) models.ItemStore {
	return &itemStore{q: sqlcgen.New(db)}
}

func (s *itemStore) List(ctx context.Context) ([]models.Item, error) {
	rows, err := s.q.ListItems(ctx)
	if err != nil {
		return nil, fmt.Errorf("list items: %w", err)
	}
	list := make([]models.Item, len(rows))
	for i, row := range rows {
		list[i] = toModel(row)
	}
	return list, nil
}

func (s *itemStore) Create(ctx context.Context, name string) (models.Item, error) {
	row, err := s.q.CreateItem(ctx, name)
	if err != nil {
		return models.Item{}, fmt.Errorf("create item: %w", err)
	}
	return toModel(row), nil
}

func toModel(row sqlcgen.Item) models.Item {
	return models.Item{ID: row.ID, Name: row.Name, CreatedAt: row.CreatedAt}
}
